def luhn_valid(s):
    # Supprimer les espaces et vérifier que le nombre n'a pas moins de deux chiffres
    s = s.replace(" ", "")
    if len(s) < 2:
        return False

    # Calculer le modulo 10 du numéro selon l'algorithme de Luhn
    def calculate_luhn_mod(number):
        total = 0
        for i in range(len(number)):
            digit = int(number[i])
            if i % 2 == 0:
                digit *= 2
                if digit > 9:
                    digit -= 9
            total += digit
        return total % 10

    # Vérifier si le résultat est égal à 0
    return calculate_luhn_mod(s) == 0
```

