def parse_duration(s):
    parts = s.split()
    total_seconds = 0

    if len(parts) == 0:
        return None

    for part in parts:
        unit = part[-1]
        value = int(part[:-1])

        if unit == 'h':
            total_seconds += value * 3600
        elif unit == 'm':
            total_seconds += value * 60
        elif unit == 's':
            total_seconds += value

    return total_seconds
