def title_case(s):
    if not s:
        return ""

    words = s.split()
    result = []

    for word in words:
        if word.lower() in {"a", "an", "the", "of", "and", "to"}:
            result.append(word)
        else:
            result.append(word.capitalize())

    return ' '.join(result)
